const b = $input.item.json.body || $input.item.json;
const task = b.task || b;

return {
  json: {
    source: 'clickup',
    eventType: b.event || 'taskUpdated',
    entityType: 'task',
    entityId: task.id || task.task_id || '',
    title: task.name || task.title || 'Untitled task',
    description: task.description || task.text_content || '',
    assignee: (task.assignees && task.assignees[0] && task.assignees[0].username) || task.assignee || 'unassigned',
    status: (task.status && task.status.status) || task.status || '',
    tags: (task.tags || []).map(t => t.name || t),
    linkedRepo: task.custom_field_repo || '',
    linkedService: task.custom_field_service || '',
    timestamp: task.date_updated || new Date().toISOString()
  }
};

const b = $input.item.json.body || $input.item.json;
const pr = b.pull_request || {};

return {
  json: {
    source: 'github',
    eventType: b.action || 'pull_request',
    entityType: 'pull_request',
    entityId: String(pr.number || ''),
    repo: (b.repository && (b.repository.full_name || b.repository.name)) || '',
    title: pr.title || '',
    description: pr.body || '',
    author: (pr.user && pr.user.login) || 'unknown',
    filesChanged: (b.files || []).map(f => f.filename),
    mergedAt: pr.merged_at || '',
    timestamp: pr.updated_at || new Date().toISOString()
  }
};

const b = $input.item.json.body || $input.item.json;
const inc = b.incident || b;

return {
  json: {
    source: 'incident',
    eventType: b.event || inc.status || 'incident',
    entityType: 'incident',
    entityId: inc.id || inc.incident_number || '',
    title: inc.title || inc.summary || 'Untitled incident',
    description: inc.description || inc.details || '',
    affectedService: (inc.service && inc.service.name) || inc.service || '',
    severity: inc.urgency || inc.severity || 'low',
    postmortemUrl: inc.postmortem_url || '',
    timestamp: inc.created_at || new Date().toISOString()
  }
};

const b = $input.item.json.body || $input.item.json;
const page = b.page || b;
const title = page.title || 'Untitled page';

return {
  json: {
    source: 'docs',
    eventType: b.event || 'pageUpdated',
    entityType: /adr|architecture decision/i.test(title) ? 'architecture_decision' : 'documentation',
    entityId: page.id || page.pageId || '',
    title,
    content: page.excerpt || page.content || '',
    author: (page.author && page.author.name) || page.author || 'unknown',
    url: page.url || '',
    timestamp: page.updatedAt || new Date().toISOString()
  }
};

// Pull the event list out of whatever the buffer API returned
const events = ($input.first().json.events || $input.first().json || []);
const list = Array.isArray(events) ? events : [];

const clearLinks = [];
const ambiguousEvents = [];

for (const e of list) {
  const links = [];

  if (e.source === 'clickup') {
    if (e.assignee && e.assignee !== 'unassigned') {
      links.push({ from: { type: 'developer', id: e.assignee }, to: { type: 'task', id: e.entityId }, relation: 'assigned_to' });
    }
    if (e.linkedRepo) links.push({ from: { type: 'task', id: e.entityId }, to: { type: 'repository', id: e.linkedRepo }, relation: 'targets' });
    if (e.linkedService) links.push({ from: { type: 'task', id: e.entityId }, to: { type: 'service', id: e.linkedService }, relation: 'targets' });
  }

  if (e.source === 'github') {
    if (e.author) links.push({ from: { type: 'developer', id: e.author }, to: { type: 'pull_request', id: e.entityId }, relation: 'authored' });
    if (e.repo) links.push({ from: { type: 'pull_request', id: e.entityId }, to: { type: 'repository', id: e.repo }, relation: 'belongs_to' });
  }

  if (e.source === 'incident') {
    if (e.affectedService) links.push({ from: { type: 'incident', id: e.entityId }, to: { type: 'service', id: e.affectedService }, relation: 'affects' });
    if (e.postmortemUrl) links.push({ from: { type: 'incident', id: e.entityId }, to: { type: 'documentation', id: e.postmortemUrl }, relation: 'documented_by' });
  }

  if (links.length > 0) clearLinks.push(...links.map(l => ({ ...l, sourceEvent: e })));

  // Free-text fields may reference other entities (repos, services, APIs, databases,
  // task IDs, incident IDs) by name that no structured field captured - flag for AI extraction
  const freeText = [e.title, e.description, e.content].filter(Boolean).join(' ');
  if (freeText) ambiguousEvents.push({ ...e, freeText });
}

return [{
  json: {
    windowTimestamp: new Date().toISOString(),
    clearLinks,
    ambiguousEvents,
    hasAmbiguous: ambiguousEvents.length > 0
  }
}];

