const item = $input.item.json;
const upstream = $('Check for Ambiguous Events').first().json;

let extracted = [];
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  extracted = parsed.extractedLinks || [];
} catch (e) {
  // Fallback: if parsing fails, skip AI-derived links this cycle rather than inventing connections
  extracted = [];
}

const aiLinks = extracted
  .filter(l => l.confidence !== 'low')
  .map(l => ({ from: l.from, to: l.to, relation: l.relation, sourceEventId: l.eventEntityId, aiExtracted: true }));

return { json: { windowTimestamp: upstream.windowTimestamp, links: [...upstream.clearLinks, ...aiLinks] } };

const allLinks = [];
for (const item of $input.all()) {
  for (const l of (item.json.links || [])) allLinks.push(l);
}

const nodesByKey = {};
const edges = [];

function upsertNode(entity) {
  if (!entity || !entity.id) return;
  const key = `${entity.type}:${entity.id}`;
  if (!nodesByKey[key]) nodesByKey[key] = { type: entity.type, id: entity.id };
}

for (const l of allLinks) {
  if (!l.from || !l.to) continue;
  upsertNode(l.from);
  upsertNode(l.to);
  edges.push({
    fromType: l.from.type,
    fromId: l.from.id,
    toType: l.to.type,
    toId: l.to.id,
    relation: l.relation,
    aiExtracted: !!l.aiExtracted,
    source: l.sourceEvent ? l.sourceEvent.source : 'ai'
  });
}

return [{
  json: {
    windowTimestamp: new Date().toISOString(),
    nodes: Object.values(nodesByKey),
    edges
  }
}];
